        // Cache the static silhouettes at their original design size and soften their edge once.
        static BitmapSource Silhouette(BambooPart[] parts)
        {
            var visual=new DrawingVisual(); using(var draw=visual.RenderOpen()) {
                draw.PushTransform(new ScaleTransform(.5,.5));
                foreach (var p in parts) draw.DrawGeometry(p.Stem==null?LeafInk:null,p.Stem,p.Shape);
                draw.Pop();
            }
            var bmp=new RenderTargetBitmap(640,360,96,96,PixelFormats.Pbgra32); bmp.Render(visual);
            // A small separable box blur matches the defocused bamboo, without a per-frame effect.
            const int w=640,h=360;var src=new byte[w*h*4];bmp.CopyPixels(src,w*4,0);var tmp=new byte[src.Length];var dst=new byte[src.Length];
            for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int k=0;k<4;k++) {int o=(y*w+x)*4+k;tmp[o]=(byte)((src[o]+src[o]+src[(y*w+Math.Max(0,x-1))*4+k]+src[(y*w+Math.Min(w-1,x+1))*4+k])/4);}
            for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int k=0;k<4;k++) {int o=(y*w+x)*4+k;dst[o]=(byte)((tmp[o]+tmp[o]+tmp[(Math.Max(y-1,0)*w+x)*4+k]+tmp[(Math.Min(h-1,y+1)*w+x)*4+k])/4);}
            return Freeze(BitmapSource.Create(w,h,96,96,PixelFormats.Pbgra32,null,dst,w*4));
        }
        static readonly BitmapSource CrownImage=Silhouette(Crown), GrassImage=Silhouette(Grass);
