            ClipToBounds=true; IsHitTestVisible=false; Focusable=false;
            using(var stream=File.OpenRead(absolutePng)) { var img=new BitmapImage();img.BeginInit();img.CacheOption=BitmapCacheOption.OnLoad;img.StreamSource=stream;img.EndInit();painting=Freeze(img); }
