        { if(w>0&&h>0) dc.DrawRectangle(brush,null,new Rect(x,y,w,h)); }
        void Background(DrawingContext dc,Rect viewport)
        {
            double W=viewport.Width,H=viewport.Height,t=TimeSeconds,wind=Math.Sin(t*.86)+.35*Math.Sin(t*1.67+.6);
            dc.DrawRectangle(Room,null,viewport);Box(dc,Beam,(-.08+wind*.0085)*W,-.08*H,1.16*W,1.16*H);
            dc.PushOpacity(.50); dc.PushTransform(new TranslateTransform(0,wind*2)); dc.PushTransform(new RotateTransform(wind*1.8,W,0)); dc.DrawImage(CrownImage,viewport); dc.Pop();dc.Pop();dc.Pop();
            dc.PushOpacity(.355);dc.PushTransform(new RotateTransform(Math.Sin(t*.77-.8)*1.6,0,H));dc.DrawImage(GrassImage,viewport);dc.Pop();dc.Pop();
            for(int i=0;i<9;i++) dc.DrawEllipse(Dust,null,new Point(W*(52+i*31%46)/100+14*Math.Sin(t*.28+i*.9),H*(5+i*19%56)/100+8*Math.Cos(t*.36+i*2.7)),1,1);
        }
        void Roller(DrawingContext dc,Rect art,double x,double r,double baseR,bool moving)
        {
            double top=art.Top-baseR*.61,bottom=art.Bottom+baseR*.61;
            for(int i=0;i<2;i++){ double edge=i==0?top:bottom;
                Box(dc,Wood,x-r*.55,edge+(i==0?-2.15*baseR:0),r*1.10,baseR*2.15);
                Box(dc,Brass,x-r*.68,edge+(i==0?-1.98*baseR:1.79*baseR),r*1.36,baseR*.19);
                Box(dc,Brass,x-r*.69,edge+(i==0?-.52*baseR:.28*baseR),r*1.38,baseR*.24);
            }
            Box(dc,moving?Paper:Wood,x-r,top,2*r,bottom-top); if(!moving)return;
            // Map narrow vertical intervals around the curved, travelling paper surface.
            int n=Math.Max(14,(int)Math.Ceiling(2*r));double dw=2*r/n;
            for(int j=0;j<n;j++) { double a=Math.Asin(2*(j+.5)/n-1),u=Unit((x-art.Left-(a*r+r*.1))/art.Width);
                var strip=new ImageBrush(painting){ViewboxUnits=BrushMappingMode.RelativeToBoundingBox,Viewbox=new Rect(Math.Min(u,1-1.8/painting.PixelWidth),0,1.8/painting.PixelWidth,1),Stretch=Stretch.Fill};
                Box(dc,strip,x-r+j*dw,art.Top,dw+.45,art.Height);
            }
            Box(dc,Glaze,x-r,top,2*r,bottom-top);
        }
