            if(z>0){double scale=Math.Max(W/art.Width,H/art.Height)*1.23,fw=art.Width*scale,fh=art.Height*scale;
                double fx=Math.Min(0,Math.Max(W-fw,W*.5-Centers[Math.Max(0,Math.Min(3,Selection))]*fw)),fy=(H-fh)*.52;
                dc.DrawImage(painting,new Rect(Mix(art.X,fx,z),Mix(art.Y,fy,z),Mix(art.Width,fw,z),Mix(art.Height,fh,z)));
                if(z>.48){dc.PushOpacity(Unit((z-.48)/.52));dc.DrawRectangle(TitleWash,null,viewport);dc.Pop();}return;
            }
            double u=Unit(Open),r=Math.Min(24,Math.Max(7,art.Width*.019)),left=art.Right-art.Width*(.063+.937*u),rad=r*(.63+.53*Math.Sqrt(1-u));
            double width=art.Right-left,trim=r*.55;for(int i=7;i>0;i--){double spread=i*r*.14;Box(dc,Shade,left-spread,art.Top-trim-spread+r*.55,width+2*spread,art.Height+2*(trim+spread));}
            Box(dc,Mount,left,art.Top-trim,width,art.Height+2*trim);
            dc.PushClip(new RectangleGeometry(new Rect(left,art.Top,width,art.Height)));dc.DrawImage(painting,art);dc.Pop();
            Box(dc,TopSeam,left,art.Top-2,width,1);Box(dc,BottomSeam,left,art.Bottom+1,width,1);
            Box(dc,Contact,left,art.Top-trim,Math.Min(width,rad*3.5),art.Height+2*trim);
            Roller(dc,art,art.Right+r*.36,r*.5,r,false);Roller(dc,art,left,rad,r,true);
